#include <cassert>
#include "include/cef_api_hash.h"
#include "network_authentication.h"
int main(){assert(cef_api_hash(CEF_API_VERSION,0));using Auth=suitecut::NativeNetworkAuthentication;using Dict=Auth::Dict;std::vector<Auth::Result>pending;std::vector<Dict>sent;std::string failure;Auth auth([&](const std::string&,const std::string&method,Dict params,Auth::Result done){assert(method=="Fetch.continueWithAuth");sent.push_back(params->Copy(false));pending.push_back(std::move(done));},[&](const std::string&error){failure=error;},[]{});
 auto input=CefDictionaryValue::Create();input->SetString("requestId","actual-fetch-identity");auto request=CefDictionaryValue::Create();request->SetString("url","https://native.test/actual");input->SetDictionary("request",request);auto challenge=CefDictionaryValue::Create();challenge->SetString("source","Server");challenge->SetString("realm","actual native realm");input->SetDictionary("authChallenge",challenge);
 int provided=0;auth.Set([&](Dict actual){assert(actual->GetDictionary("authChallenge")->GetString("realm")=="actual native realm");++provided;auto response=CefDictionaryValue::Create();response->SetString("response","ProvideCredentials");response->SetString("username","actual user");response->SetString("password","actual password");return response;});
 for(int i=0;i<4;++i){auth.Event(input,"actual-session",0);assert(auth.pending()==1);pending.back()(true,"");assert(auth.pending()==0);}assert(provided==3&&sent.back()->GetDictionary("authChallengeResponse")->GetString("response")=="CancelAuth");
 auth.Event(input,"actual-session",1);assert(auth.pending()==1);auth.SessionDetached("actual-session");pending.back()(false,"late reply");assert(failure.empty()&&auth.pending()==0);
 for(int i=0;i<2000;++i){const auto fetch="completed-"+std::to_string(i),network="native-network-"+std::to_string(i);input->SetString("requestId",fetch);auth.Paused("parent-session",fetch,"worker-session",network,2);auth.Event(input,"parent-session",2);auth.NetworkFinished("worker-session",network);assert(auth.pending()==1);pending.back()(true,"");assert(auth.pending()==0&&!auth.NeedsTick());}input->SetString("requestId","actual-fetch-identity");
 input->SetString("requestId","actual-late-worker-network");auth.Paused("parent-session","actual-late-worker-network","parent-session","actual-worker-network",2);auth.Event(input,"parent-session",2);auth.NetworkMoved("actual-worker-network","parent-session","worker-session");auth.NetworkFinished("worker-session","actual-worker-network");pending.back()(true,"");assert(!auth.NeedsTick());
 input->SetString("requestId","cross-session-detached");auth.Paused("parent-session","cross-session-detached","worker-session","actual-worker-request",2);auth.Event(input,"parent-session",2);auth.SessionDetached("worker-session");assert(auth.pending()==0&&!auth.NeedsTick());pending.back()(false,"late detached auth ACK");assert(failure.empty());input->SetString("requestId","actual-fetch-identity");
 auth.Event(input,"actual-session",2);auth.Tick(30002);assert(!failure.empty()&&auth.failed()&&auth.pending()==1);const auto original_error=failure;auth.Tick(60002);assert(failure==original_error&&auth.pending()==1);auth.Clear();assert(auth.pending()==0);pending.back()(true,"");
 std::vector<Auth::Result>rejected_callbacks;int failures=0;Auth rejected([&](const std::string&,const std::string&,Dict,Auth::Result done){rejected_callbacks.push_back(std::move(done));},[&](const std::string&){++failures;},[]{});rejected.Set([](Dict){auto decision=CefDictionaryValue::Create();decision->SetString("response","CancelAuth");return decision;});rejected.Event(input,"actual-rejected-session",0);assert(rejected.pending()==1);rejected_callbacks[0](false,"actual native response rejection");assert(rejected.failed()&&rejected.pending()==1&&failures==1);rejected_callbacks[0](true,"");assert(rejected.pending()==1);rejected.Clear();assert(rejected.pending()==0);
}
